44	function hashString(s: string): number {
45	  let h = 2166136261;
46	  for (let i = 0; i < s.length; i++) {
47	    h ^= s.charCodeAt(i);
48	    h = Math.imul(h, 16777619);
49	  }
50	  return h >>> 0;
