53	// mulberry32: tiny, fast, deterministic.
54	function seededRandom(seed: number): () => number {
55	  let a = seed;
56	  return () => {
57	    a |= 0;
58	    a = (a + 0x6d2b79f5) | 0;
59	    let t = Math.imul(a ^ (a >>> 15), 1 | a);
60	    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
61	    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
62	  };
