71	// Rejection-sampled star placement: nothing crowds, nothing clips, and the
72	// figure keeps to the upper sky so the name owns the bottom of the card.
73	function placeMajors(rand: () => number, count: number): Array<{ x: number; y: number }> {
74	  const points: Array<{ x: number; y: number }> = [];
75	  let tries = 0;
76	  while (points.length < count && tries < 600) {
77	    tries++;
78	    const x = PAD + rand() * (W - PAD * 2);
79	    const y = PAD + rand() * (H * 0.62 - PAD);
80	    const crowded = points.some((p) => {
81	      const dx = p.x - x;
82	      const dy = p.y - y;
83	      return dx * dx + dy * dy < MIN_SEPARATION * MIN_SEPARATION;
84	    });
85	    if (!crowded) points.push({ x, y });
