90	// Prim's minimum spanning tree: each star joins its nearest branch, which is
91	// why real star charts look calm instead of criss-crossed.
92	function spanningTree(points: Array<{ x: number; y: number }>): Array<[number, number]> {
93	  const inTree = [0];
94	  const edges: Array<[number, number]> = [];
95	  while (inTree.length < points.length) {
96	    let best: { i: number; j: number; d: number } | null = null;
97	    for (const i of inTree) {
98	      for (let j = 0; j < points.length; j++) {
99	        if (inTree.includes(j)) continue;
100	        const dx = points[i].x - points[j].x;
101	        const dy = points[i].y - points[j].y;
102	        const d = dx * dx + dy * dy;
103	        if (best === null || d < best.d) best = { i, j, d };
104	      }
105	    }
106	    if (best === null) break;
107	    edges.push([best.i, best.j]);
108	    inTree.push(best.j);
109	  }
110	  return edges;
111	}
