113	export function buildSky(name: string, handle?: string): SkyData {
114	  const rand = seededRandom(hashString(name + (handle ?? "")));
115	  const hues = personHues(name, handle);
116	
117	  const nebulae = [
118	    { cx: W * 0.35, cy: H * 0.25, rx: W * 0.75, ry: H * 0.42, hue: hues[0], alpha: 0.18 },
119	    { cx: W * 0.75, cy: H * 0.5, rx: W * 0.65, ry: H * 0.36, hue: hues[1], alpha: 0.15 },
120	    { cx: W * 0.4, cy: H * 0.7, rx: W * 0.6, ry: H * 0.3, hue: hues[2], alpha: 0.13 },
121	  ];
122	
123	  // Depth: many faint stars on a power law -- the difference between a
124	  // diagram and a sky.
125	  const minors: SkyStar[] = [];
126	  for (let i = 0; i < MINOR_COUNT; i++) {
127	    const hi = 0.25 + rand() * 0.55;
128	    minors.push({
129	      x: rand() * W,
130	      y: rand() * H,
131	      r: 0.4 + Math.pow(rand(), 2.6) * 1.4,
132	      hi,
133	      lo: Math.max(0.08, hi - 0.3),
134	      dur: 2.6 + rand() * 4.5,
135	      delay: rand() * 6,
136	      rvd: rand(),
137	    });
138	  }
139	
140	  // A few colored giants, like a telescope frame.
141	  const giants: SkyMajor[] = [];
142	  for (let i = 0; i < 5; i++) {
143	    giants.push({
144	      x: PAD + rand() * (W - PAD * 2),
145	      y: PAD + rand() * (H * 0.8),
146	      r: 1.2 + rand(),
147	      hue: hues[i % 3],
148	      hi: 0.9,
149	      lo: 0.5,
150	      dur: 3 + rand() * 3,
151	      delay: rand() * 4,
152	      rvd: rand(),
153	    });
154	  }
155	
156	  const placed = placeMajors(rand, 7 + Math.floor(rand() * 2));
157	  const edges = spanningTree(placed);
158	  const majors: SkyMajor[] = placed.map((p, i) => ({
159	    x: p.x,
160	    y: p.y,
161	    r: 1.5 + rand() * 1.9,
162	    hue: hues[i % 3],
163	    hi: 1,
164	    lo: 0.62,
165	    dur: 3 + rand() * 3.4,
166	    delay: rand() * 5,
167	    rvd: rand(),
168	  }));
169	
170	  // The two brightest stars in the figure earn diffraction flares.
171	  const byBrightness = majors
172	    .map((m, i) => ({ r: m.r, i }))
173	    .sort((a, b) => b.r - a.r)
174	    .slice(0, 2);
175	  const flares = byBrightness.map(({ r, i }) => ({
176	    x: majors[i].x,
177	    y: majors[i].y,
178	    len: r * 9,
179	    dur: 4 + rand() * 3,
180	    delay: rand() * 4,
181	  }));
182	
183	  const sx = 40 + rand() * 160;
184	  const sy = 30 + rand() * 120;
185	  const shoot = { x1: sx, y1: sy, x2: sx - 34, y2: sy - 19, delay: 3 + rand() * 8 };
186	
187	  // Pick the featured minors LAST -- after every other draw above -- so the
188	  // giants, constellation, flares and shooting star stay byte-identical to
189	  // before this flag existed. Drawing here shifts no earlier value, so no
190	  // figure moves; only the boolean on the chosen minors changes. Partial
191	  // Fisher-Yates over the same seeded stream keeps the pick stable per person.
192	  const order = minors.map((_, i) => i);
193	  const featureCount = Math.min(FEATURED_MINORS, order.length);
