214	// A person's constellation shrunk to a map cluster. It reuses buildSky's
215	// majors + edges so the figure on the atlas is recognizably the SAME shape as
216	// on their card and detail sky -- identity, not decoration. Minors are dropped;
217	// the shared dust field carries the faint-star texture instead.
218	export function buildCluster(
219	  name: string,
220	  handle?: string,
221	  opts?: { width?: number; height?: number; pad?: number },
222	): ClusterData {
223	  const width = opts?.width ?? 120;
224	  const height = opts?.height ?? 92;
225	  const pad = opts?.pad ?? 8;
226	  const sky = buildSky(name, handle);
227	
228	  const xs = sky.majors.map((m) => m.x);
229	  const ys = sky.majors.map((m) => m.y);
230	  const minX = Math.min(...xs);
231	  const maxX = Math.max(...xs);
232	  const minY = Math.min(...ys);
233	  const maxY = Math.max(...ys);
234	  // Guard the degenerate single-column/row case so we never divide by zero.
235	  const spanX = maxX - minX || 1;
236	  const spanY = maxY - minY || 1;
237	  const innerW = Math.max(0, width - pad * 2);
238	  const innerH = Math.max(0, height - pad * 2);
239	
240	  const stars: ClusterStar[] = sky.majors.map((m) => ({
241	    x: pad + ((m.x - minX) / spanX) * innerW,
242	    y: pad + ((m.y - minY) / spanY) * innerH,
243	    // Map the card radius (~1.5..3.4) into a small, readable map radius.
244	    r: 1.1 + (m.r - 1.5) * 0.5,
245	    hue: m.hue,
246	  }));
247	
248	  return { width, height, stars, edges: sky.edges };
249	}
