261	// One shared field of faint background stars behind every cluster -- seeded
262	// from a fixed string, NOT per person, so the whole sky twinkles as one. Unit
263	// coordinates keep it resolution-independent across resizes.
264	export function buildDust(count = 80, seed = "haven-atlas-dust"): DustStar[] {
265	  const rand = seededRandom(hashString(seed));
266	  const dust: DustStar[] = [];
267	  for (let i = 0; i < count; i++) {
268	    dust.push({
269	      x: rand(),
270	      y: rand(),
271	      r: 0.4 + rand() * 0.7,
272	      // Deliberately dim: dust must never compete with a person's stars.
273	      hi: 0.18 + rand() * 0.16,
274	      lo: 0.06 + rand() * 0.06,
275	      dur: 3 + rand() * 4,
276	      delay: rand() * 4,
277	    });
