282	// Golden-angle spiral placement, ordered by the recent-first query: index 0
283	// (newest) sits nearest the center, each later person spirals outward. The y
284	// radius is squashed so the field reads as a wide sky rather than a disc.
285	// maxR is capped so the outermost cluster's full box + label never leaves the
286	// viewport -- the layout, not the caller, owns staying in bounds.
287	export function atlasLayout(
288	  count: number,
289	  width: number,
290	  height: number,
291	  opts?: {
292	    boxW?: number;
293	    boxH?: number;
294	    labelH?: number;
295	    centerYOffset?: number;
296	  },
297	): Array<{ x: number; y: number }> {
298	  const boxW = opts?.boxW ?? 120;
299	  const boxH = opts?.boxH ?? 92;
300	  const labelH = opts?.labelH ?? 46;
301	  const centerYOffset = opts?.centerYOffset ?? 14;
302	
303	  const cx = width / 2;
304	  const cy = height / 2 + centerYOffset;
305	  const squash = 0.82;
306	
307	  // Room the outermost cluster needs on each side (label only hangs below).
308	  const marginX = boxW / 2 + 8;
309	  const marginTop = boxH / 2 + 8;
310	  const marginBottom = boxH / 2 + labelH + 8;
311	
312	  const maxRx = Math.min(cx - marginX, width - cx - marginX);
313	  const maxRy = Math.min(cy - marginTop, height - cy - marginBottom) / squash;
314	  const maxR = Math.max(0, Math.min(maxRx, maxRy, Math.min(width, height) * 0.42));
315	
316	  const n = Math.max(count, 1);
317	  const points: Array<{ x: number; y: number }> = [];
318	  for (let i = 0; i < count; i++) {
319	    const angle = i * 2.399963; // golden angle in radians
320	    const rad = maxR * Math.sqrt((i + 0.7) / n);
321	    points.push({
322	      x: cx + Math.cos(angle) * rad,
323	      y: cy + Math.sin(angle) * rad * squash,
324	    });
325	  }
326	  return points;
327	}
